def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    def tft(history):
        n = len(history)
        last_me, last_opp = history[-1]
        opp_defects = sum(1 for _, o in history if o == 'D')
        opp_def_rate = opp_defects / n
        if last_opp == 'D':
            if opp_def_rate > 0.4:
                return 'D'
            if last_me == 'C':
                if opp_def_rate < 0.25:
                    return 'C'
                return 'D'
            else:
                if opp_def_rate < 0.5:
                    return 'C'
                return 'D'
        else:
            if last_me == 'D':
                return 'C'
            else:
                if n >= 99:
                    return 'D'
                return 'C'

    early_def = any(history[i][1] == 'D' for i in range(min(10, n)))
    if n < 9:
        if early_def:
            return tft(history)
        return 'C'
    if n == 9:
        if early_def:
            return tft(history)
        return 'D'
    if n == 10:
        if early_def:
            return tft(history)
        return 'C'
    if early_def:
        return tft(history)
    probe_response = history[10][1]
    if probe_response == 'D':
        return tft(history)
    recent = history[-3:]
    if any(o == 'D' for _, o in recent):
        return tft(history)
    return 'D'
